  getIonStorage(){
    debugger
    this.ionicstorage.getData('SecSidsSchlGenrlInfoGetRmrks').then(
      (data) => {
        if(data != null && data != undefined){
          this.schlDataRmks = {};
          for (let i = 0; i < data.length; i++) {
            for (const key in data[i]) {
              let gtData = data[i]
              if(key != 'question_id' && key != 'remarks' && key != 'hm_status_yn'){
                this.gtKey = key
              }

              if(typeof this.schlDataRmks[this.gtKey] == 'undefined'){this.schlDataRmks[this.gtKey] = {}}
              if(key == 'remarks'){
                this.schlDataRmks[this.gtKey][key] = gtData[key]
              }
              else if(key == 'hm_status_yn'){
                this.schlDataRmks[this.gtKey][key] = gtData[key]
              }
            }        
          }
          
          console.log(this.schlDataRmks, 'keyName')
        }
      },
      (error) => {
        this.alertService.error(error);
      }
    );
  }

